const wchar_t* Find(std::string_view key, std::wstring_view lang) {
    const auto it = std::lower_bound(std::begin(kEntries), std::end(kEntries), key,
                                     [](const Entry& e, std::string_view k) { return std::string_view(e.key) < k; });
    if (it == std::end(kEntries) || std::string_view(it->key) != key) return nullptr;
    const int index = lang == L"es" ? 1 : lang == L"fr" ? 2 : lang == L"it" ? 3 : 0;
    return it->text[index];
}

